from typing import Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def getDirections(self, root: Optional[TreeNode], startValue: int, destValue: int) -> str:
        def find_path(node: Optional[TreeNode], target: int, path: list[str]) -> bool:
            if not node:
                return False
            if node.val == target:
                return True
            path.append('L')
            if find_path(node.left, target, path):
                return True
            path.pop()

            path.append('R')
            if find_path(node.right, target, path):
                return True
            path.pop()

            return False

        start_path: list[str] = []
        dest_path: list[str] = []

        find_path(root, startValue, start_path)
        find_path(root, destValue, dest_path)

        i = 0
        min_len = min(len(start_path), len(dest_path))
        while i < min_len and start_path[i] == dest_path[i]:
            i += 1

        up_steps = 'U' * (len(start_path) - i)
        down_steps = ''.join(dest_path[i:])

        return up_steps + down_steps

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
#include <string>
#include <algorithm>

class Solution {
public:
    std::string getDirections(TreeNode* root, int startValue, int destValue) {
        std::string startPath, destPath;
        findPath(root, startValue, startPath);
        findPath(root, destValue, destPath);

        int i = 0;
        int minLen = std::min(startPath.size(), destPath.size());
        while (i < minLen && startPath[i] == destPath[i]) {
            i++;
        }

        std::string upSteps(startPath.size() - i, 'U');
        std::string downSteps = destPath.substr(i);

        return upSteps + downSteps;
    }

private:
    bool findPath(TreeNode* node, int target, std::string& path) {
        if (!node) return false;
        if (node->val == target) return true;

        path.push_back('L');
        if (findPath(node->left, target, path)) return true;
        path.pop_back();

        path.push_back('R');
        if (findPath(node->right, target, path)) return true;
        path.pop_back();

        return false;
    }
};

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        StringBuilder startPath = new StringBuilder();
        StringBuilder destPath = new StringBuilder();

        findPath(root, startValue, startPath);
        findPath(root, destValue, destPath);

        int i = 0;
        int minLen = Math.min(startPath.length(), destPath.length());
        while (i < minLen && startPath.charAt(i) == destPath.charAt(i)) {
            i++;
        }

        StringBuilder sb = new StringBuilder();
        for (int k = i; k < startPath.length(); k++) {
            sb.append('U');
        }
        sb.append(destPath.substring(i));

        return sb.toString();
    }

    private boolean findPath(TreeNode node, int target, StringBuilder path) {
        if (node == null) return false;
        if (node.val == target) return true;

        path.append('L');
        if (findPath(node.left, target, path)) return true;
        path.setLength(path.length() - 1);

        path.append('R');
        if (findPath(node.right, target, path)) return true;
        path.setLength(path.length() - 1);

        return false;
    }
}

/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number} startValue
 * @param {number} destValue
 * @return {string}
 */
var getDirections = function(root, startValue, destValue) {
    const startPath = [];
    const destPath = [];

    const findPath = (node, target, path) => {
        if (!node) return false;
        if (node.val === target) return true;

        path.push('L');
        if (findPath(node.left, target, path)) return true;
        path.pop();

        path.push('R');
        if (findPath(node.right, target, path)) return true;
        path.pop();

        return false;
    };

    findPath(root, startValue, startPath);
    findPath(root, destValue, destPath);

    let i = 0;
    const minLen = Math.min(startPath.length, destPath.length);
    while (i < minLen && startPath[i] === destPath[i]) {
        i++;
    }

    const upSteps = 'U'.repeat(startPath.length - i);
    const downSteps = destPath.slice(i).join('');

    return upSteps + downSteps;
};
